from harness.models import Action, ActionType, RiskLevel, ToolResult


class ToolExecutor:
    def __init__(self, workspace_root: Path | str, default_timeout_seconds: float = 10.0):
        self.workspace_root = Path(workspace_root).resolve(strict=False)
        self.default_timeout_seconds = default_timeout_seconds
        self.path_fence = PathFence(self.workspace_root)
        self.risk_classifier = RiskClassifier()

    def execute(self, action: Action) -> ToolResult:
        governance_result = self._check_governance(action)
        if governance_result is not None:
            return governance_result
        if action.type == ActionType.READ_FILE:
            path = self.path_fence.resolve(action.payload["path"])
            return ToolResult(action_id=action.request_id, ok=True, stdout=path.read_text())
        if action.type == ActionType.WRITE_FILE:
            path = self.path_fence.resolve(action.payload["path"])
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(action.payload["content"])
            return ToolResult(action_id=action.request_id, ok=True)
        if action.type == ActionType.RUN_COMMAND:
            return self._run_command(action, action.payload["command"])
        if action.type == ActionType.RUN_CHECKS:
            return self._run_checks(action)
        raise ValueError(f"unsupported action type: {action.type}")

    def _check_governance(self, action: Action) -> ToolResult | None:
        if action.type in {ActionType.READ_FILE, ActionType.WRITE_FILE}:
            decision = self.path_fence.check_action(action)
        elif action.type == ActionType.RUN_COMMAND:
            decision = self.risk_classifier.classify(action)
        else:
            return None

        if decision.level == RiskLevel.DENY:
            return ToolResult(action_id=action.request_id, ok=False, stderr="denied_by_governance")
        if decision.level == RiskLevel.REVIEW:
            return ToolResult(action_id=action.request_id, ok=False, stderr="approval_required")
        return None

    def _run_checks(self, action: Action) -> ToolResult:
        pytest_result = self._run_command(action, "pytest")
        if not pytest_result.ok:
            return pytest_result
        ruff_result = self._run_command(action, "ruff check src tests")
        if not ruff_result.ok:
            return ruff_result
        return ToolResult(
            action_id=action.request_id,
            ok=True,
            stdout=pytest_result.stdout + ruff_result.stdout,
            stderr=pytest_result.stderr + ruff_result.stderr,
            exit_code=0,
            duration_ms=(pytest_result.duration_ms or 0) + (ruff_result.duration_ms or 0),
        )

    def _run_command(self, action: Action, command: str) -> ToolResult:
        started = time.monotonic()
        try:
            completed = subprocess.run(
                command,
                shell=True,
                cwd=self.workspace_root,
                capture_output=True,
                text=True,
                timeout=self.default_timeout_seconds,
            )
        except subprocess.TimeoutExpired as exc:
            return ToolResult(
                action_id=action.request_id,
                ok=False,
                stdout=exc.stdout or "",
                stderr=exc.stderr or "",
                timed_out=True,
                duration_ms=int((time.monotonic() - started) * 1000),
            )

        return ToolResult(
            action_id=action.request_id,
            ok=completed.returncode == 0,
            stdout=completed.stdout,
            stderr=completed.stderr,
            exit_code=completed.returncode,
            duration_ms=int((time.monotonic() - started) * 1000),
        )

import re
import shlex

from harness.models import Action, ActionType, RiskDecision, RiskLevel


class RiskClassifier:
    _SHELL_OPERATOR_PATTERN = re.compile(r"[;&|\r\n]")
    _DENY_PATTERNS = (
        "drop database",
        "truncate table",
        ".env",
        ".npmrc",
        ".pypirc",
        "id_rsa",
        "id_ed25519",
        "rm -rf /",
        "del /s",
        "format",
    )
    _REVIEW_PREFIXES = (
        ("git", "push"),
        ("pip", "install"),
        ("npm", "install"),
        ("poetry", "add"),
        ("curl",),
        ("wget",),
        ("uvicorn",),
        ("python", "-m", "http.server"),
    )
    _ALLOW_PREFIXES = (
        ("pytest",),
        ("python", "-m", "pytest"),
        ("ruff",),
        ("git", "status"),
        ("git", "diff"),
    )

    def classify(self, action: Action) -> RiskDecision:
        if action.type != ActionType.RUN_COMMAND:
            return RiskDecision(level=RiskLevel.ALLOW, reasons=["non-command action"])

        command = action.payload.get("command", "")
        if not isinstance(command, str):
            return RiskDecision(level=RiskLevel.ALLOW, reasons=["command is not a string"])

        parts = [part.lower() for part in shlex.split(command, posix=False)]
        normalized = " ".join(parts)

        if any(pattern in normalized for pattern in self._DENY_PATTERNS):
            return RiskDecision(level=RiskLevel.DENY, reasons=["command matches a deny pattern"])

        if self._SHELL_OPERATOR_PATTERN.search(command):
            return RiskDecision(
                level=RiskLevel.REVIEW,
                reasons=["composite shell command requires review"],
            )

        if "--host 0.0.0.0" in normalized or self._starts_with(parts, self._REVIEW_PREFIXES):
            return RiskDecision(level=RiskLevel.REVIEW, reasons=["command requires review"])

        if self._starts_with(parts, self._ALLOW_PREFIXES):
            return RiskDecision(level=RiskLevel.ALLOW, reasons=["command is explicitly allowed"])

        return RiskDecision(level=RiskLevel.ALLOW, reasons=["command has no elevated risk pattern"])

    @staticmethod
    def _starts_with(parts: list[str], prefixes: tuple[tuple[str, ...], ...]) -> bool:
        return any(tuple(parts[: len(prefix)]) == prefix for prefix in prefixes)

from pathlib import Path

from harness.models import Action, ActionType, RiskDecision, RiskLevel


class PathFenceError(ValueError):
    """Raised when an action does not contain a usable path."""


class PathFence:
    _SENSITIVE_NAMES = {".env", ".env.local", ".npmrc", ".pypirc", "id_rsa", "id_ed25519"}

    def __init__(self, workspace_root: Path | str):
        self.workspace_root = Path(workspace_root).resolve(strict=False)

    def resolve(self, candidate: Path | str) -> Path:
        return Path(candidate).resolve(strict=False) if Path(candidate).is_absolute() else (
            self.workspace_root / candidate
        ).resolve(strict=False)

    def check_action(self, action: Action) -> RiskDecision:
        if action.type not in {ActionType.READ_FILE, ActionType.WRITE_FILE}:
            return RiskDecision(
                level=RiskLevel.DENY,
                reasons=["unsupported action type for path fence"],
            )

        candidate = action.payload.get("path")
        if not isinstance(candidate, (Path, str)):
            raise PathFenceError("action payload must contain a path")

        resolved = self.resolve(candidate)
        try:
            resolved.relative_to(self.workspace_root)
        except ValueError:
            return RiskDecision(level=RiskLevel.DENY, reasons=["path is outside workspace"])

        if resolved.name.casefold() in self._SENSITIVE_NAMES:
            return RiskDecision(
                level=RiskLevel.DENY,
                reasons=["path is a sensitive credential file"],
            )

        try:
            relative = resolved.relative_to(self.workspace_root)
        except ValueError:
            return RiskDecision(level=RiskLevel.DENY, reasons=["path is outside workspace"])
        if ".git" in relative.parts:
            return RiskDecision(level=RiskLevel.REVIEW, reasons=["path is git metadata"])

        return RiskDecision(level=RiskLevel.ALLOW, reasons=["path is inside workspace"])

